-- Phase 04 (group A): row-level security on every table carrying a tenant
-- column directly. 148 tables.
--
-- The tenant travels on the connection: each request opens a transaction and
-- issues SET LOCAL app.workspace_id, taken from the verified session and never
-- from the URL. NULLIF is essential — once a SET LOCAL ends the setting reads
-- back as an empty string, and ''::uuid raises an error instead of matching
-- nothing. NULL simply compares false, so an unset tenant sees zero rows.
--
-- USING governs reads, WITH CHECK governs writes, and WITH CHECK never allows
-- NULL: a row may be readable as global but must still be written with an
-- owner.
--
-- patients and notifications also accept NULL as "global, visible to every
-- facility" — that is a deliberate state with an admin route behind it
-- (/api/admin/patients/make-global), and 160 of 169 patients rely on it.
-- Everywhere else a NULL would be an orphan and stays invisible.
--
-- FORCE is included so table ownership cannot bypass the policy either.
--
-- Applied to production on 2026-08-22. Invisible to the running application
-- until its connection string moves to app_user: neondb_owner has BYPASSRLS.

ALTER TABLE "ap_invoices" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "ap_invoices" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "ap_invoices";
CREATE POLICY tenant_isolation ON "ap_invoices" USING (workspaceid = NULLIF(current_setting('app.workspace_id', true), '')::uuid) WITH CHECK (workspaceid = NULLIF(current_setting('app.workspace_id', true), '')::uuid);
